4	// ── The anti-bill-shock contract ──────────────────────────────────────────
5	// 1. A credit is a fixed, published amount of real model spend. No mystery units.
6	// 2. We charge from METERED tokens after a build succeeds — never a flat guess.
7	// 3. A build that fails is recorded with its true cost and charged ZERO.
8	// This is Kodely's clearest wedge against the category (see the board's
9	// "credit bill-shock" differentiation cards), so it lives in one small module.
10	
11	/** One credit = $0.002 of underlying model spend (500 credits = $1). */
12	export const MICROS_PER_CREDIT = 2_000;
13	
14	/** New accounts start with enough to build and iterate on a real page. */
15	export const SIGNUP_GRANT = 250;
16	
17	export type Usage = {
18	  inputTokens: number;
19	  outputTokens: number;
20	  cacheReadTokens: number;
21	  cacheWriteTokens: number;
22	};
23	
24	/** Micro-dollars of real model spend for a given usage on a given model. */
25	export function costMicros(model: string, usage: Usage): number {
26	  const rate = MODEL_RATES[model] ?? MODEL_RATES.default;
27	  const perToken = (perMTok: number, tokens: number) => (perMTok * tokens) / 1_000_000;
28	  return Math.round(
29	    perToken(rate.input, usage.inputTokens) +
30	      perToken(rate.output, usage.outputTokens) +
31	      perToken(rate.cacheRead, usage.cacheReadTokens) +
32	      perToken(rate.cacheWrite, usage.cacheWriteTokens),
33	  );
34	}
35	
36	export function creditsFor(micros: number): number {
37	  return Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));
38	}
