.btn-ghost:hover { border-color: var(--brand); color: var(--brand); }

/* Story */
.story { padding: clamp(3rem, 6vw, 5rem) 0; }
.story h2, .menu h2, .visit h2 {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2.1rem);
